macro_rules! deps {
    () => {
        Value!();
        Number!();
        Integer!();
    };
}

macro_rules! Float {
    () => {
        deps!();
        # [doc = " Get exact exponent limit for radix."] pub trait Float : Number { # [doc = " Unsigned type of the same size."] type Unsigned : Integer ; # [doc = " Literal zero."] const ZERO : Self ; # [doc = " Maximum number of digits that can contribute in the mantissa."] # [doc = ""] # [doc = " We can exactly represent a float in radix `b` from radix 2 if"] # [doc = " `b` is divisible by 2. This function calculates the exact number of"] # [doc = " digits required to exactly represent that float."] # [doc = ""] # [doc = " According to the \"Handbook of Floating Point Arithmetic\","] # [doc = " for IEEE754, with emin being the min exponent, p2 being the"] # [doc = " precision, and b being the radix, the number of digits follows as:"] # [doc = ""] # [doc = " `−emin + p2 + ⌊(emin + 1) log(2, b) − log(1 − 2^(−p2), b)⌋`"] # [doc = ""] # [doc = " For f32, this follows as:"] # [doc = "     emin = -126"] # [doc = "     p2 = 24"] # [doc = ""] # [doc = " For f64, this follows as:"] # [doc = "     emin = -1022"] # [doc = "     p2 = 53"] # [doc = ""] # [doc = " In Python:"] # [doc = "     `-emin + p2 + math.floor((emin+1)*math.log(2, b) - math.log(1-2**(-p2), b))`"] # [doc = ""] # [doc = " This was used to calculate the maximum number of digits for [2, 36]."] const MAX_DIGITS : usize ; # [doc = " Bitmask for the exponent, including the hidden bit."] const EXPONENT_MASK : Self :: Unsigned ; # [doc = " Bitmask for the hidden bit in exponent, which is an implicit 1 in the fraction."] const HIDDEN_BIT_MASK : Self :: Unsigned ; # [doc = " Bitmask for the mantissa (fraction), excluding the hidden bit."] const MANTISSA_MASK : Self :: Unsigned ; # [doc = " Positive infinity as bits."] const INFINITY_BITS : Self :: Unsigned ; # [doc = " Size of the significand (mantissa) without hidden bit."] const MANTISSA_SIZE : i32 ; # [doc = " Bias of the exponent"] const EXPONENT_BIAS : i32 ; # [doc = " Exponent portion of a denormal float."] const DENORMAL_EXPONENT : i32 ; # [doc = " Maximum exponent value in float."] const MAX_EXPONENT : i32 ; # [doc = " Default number of bits to shift (or 64 - mantissa size - 1)."] const DEFAULT_SHIFT : i32 ; # [doc = " Mask to determine if a full-carry occurred (1 in bit above hidden bit)."] const CARRY_MASK : u64 ; # [doc = " Get min and max exponent limits (exact) from radix."] fn exponent_limit () -> (i32 , i32) ; # [doc = " Get the number of digits that can be shifted from exponent to mantissa."] fn mantissa_limit () -> i32 ; fn pow10 (self , n : i32) -> Self ; fn from_bits (u : Self :: Unsigned) -> Self ; fn to_bits (self) -> Self :: Unsigned ; fn is_sign_positive (self) -> bool ; # [doc = " Returns true if the float is a denormal."] # [inline] fn is_denormal (self) -> bool { self . to_bits () & Self :: EXPONENT_MASK == Self :: Unsigned :: ZERO } # [doc = " Returns true if the float is a NaN or Infinite."] # [inline] fn is_special (self) -> bool { self . to_bits () & Self :: EXPONENT_MASK == Self :: EXPONENT_MASK } # [doc = " Returns true if the float is infinite."] # [inline] fn is_inf (self) -> bool { self . is_special () && (self . to_bits () & Self :: MANTISSA_MASK) == Self :: Unsigned :: ZERO } # [doc = " Get exponent component from the float."] # [inline] fn exponent (self) -> i32 { if self . is_denormal () { return Self :: DENORMAL_EXPONENT ; } let bits = self . to_bits () ; let biased_e = ((bits & Self :: EXPONENT_MASK) >> Self :: MANTISSA_SIZE) . as_u32 () ; biased_e as i32 - Self :: EXPONENT_BIAS } # [doc = " Get mantissa (significand) component from float."] # [inline] fn mantissa (self) -> Self :: Unsigned { let bits = self . to_bits () ; let s = bits & Self :: MANTISSA_MASK ; if ! self . is_denormal () { s + Self :: HIDDEN_BIT_MASK } else { s } } # [doc = " Get next greater float for a positive float."] # [doc = " Value must be >= 0.0 and < INFINITY."] # [inline] fn next_positive (self) -> Self { debug_assert ! (self . is_sign_positive () && ! self . is_inf ()) ; Self :: from_bits (self . to_bits () + Self :: Unsigned :: as_cast (1u32)) } # [doc = " Round a positive number to even."] # [inline] fn round_positive_even (self) -> Self { if self . mantissa () & Self :: Unsigned :: as_cast (1u32) == Self :: Unsigned :: as_cast (1u32) { self . next_positive () } else { self } } }
    };
}

Float!();